const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Namibia geometry
  const namibia = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Namibia'));

  const geom = namibia.geometry();

  // Function to calculate NDVI from Sentinel-2
  function addNDVI(img) {
    const ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return img.addBands(ndvi);
  }

  // Function to mask clouds using SCL
  function maskClouds(img) {
    const scl = img.select('SCL');
    const mask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    return img.updateMask(mask);
  }

  // Fallback to MODIS if Sentinel-2 fails
  function addNDVIModis(img) {
    const ndvi = img.normalizedDifference(['B2', 'B1']).rename('NDVI');
    return img.addBands(ndvi);
  }

  function maskModis(img) {
    const qa = img.select('StateQA');
    const mask = qa.bitwiseAnd(1).eq(0); // Good quality pixels
    return img.updateMask(mask);
  }

  // 2019 Feb 21-28
  let col2019 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(geom)
    .filterDate('2019-02-21', '2019-02-29')
    .map(maskClouds)
    .map(addNDVI);

  let size2019 = col2019.size().getInfo();
  console.log('2019 Sentinel-2 images:', size2019);

  // Fallback to MODIS for 2019 if no Sentinel-2
  if (size2019 === 0) {
    col2019 = ee.ImageCollection('MODIS/006/MOD13Q1')
      .filterBounds(geom)
      .filterDate('2019-02-21', '2019-02-29')
      .map(maskModis)
      .map(addNDVIModis);
    size2019 = col2019.size().getInfo();
    console.log('2019 MODIS images (fallback):', size2019);
  }

  if (size2019 === 0) {
    console.log('No data for 2019.');
    console.log('C1');
    return;
  }

  // Calculate mean NDVI for 2019
  const img2019 = col2019.mean();
  const count2019 = img2019.select('NDVI')
    .reduceRegion(reducer=ee.Reducer.count(), geometry=geom, scale=3000, maxPixels=1e9)
    .get('NDVI').getInfo();

  if (count2019 === 0) {
    console.log('No valid pixels in 2019 after masking.');
    console.log('C2');
    return;
  }

  const ndvi2019 = img2019.select('NDVI')
    .reduceRegion(reducer=ee.Reducer.mean(), geometry=geom, scale=3000, maxPixels=1e9)
    .get('NDVI').getInfo();

  console.log('2019 NDVI:', ndvi2019, '| Valid pixels:', count2019);

  // Baseline 2003-2017, Feb 21-28
  let colBaseline = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(geom)
    .filter(ee.Filter.daysBetween({
      'start': ee.Date('2003-02-21'),
      'end': ee.Date('2017-02-28'),
      'leftField': 'system:time_start'
    }))
    .filter(ee.Filter.calendarRange(2, 2, 'month'))
    .filter(ee.Filter.calendarRange(21, 28, 'day_of_year'))
    .map(maskClouds)
    .map(addNDVI);

  let sizeBaseline = colBaseline.size().getInfo();
  console.log('Baseline Sentinel-2 images:', sizeBaseline);

  // Fallback to MODIS
  if (sizeBaseline === 0) {
    colBaseline = ee.ImageCollection('MODIS/006/MOD13Q1')
      .filterBounds(geom)
      .filter(ee.Filter.daysBetween({
        'start': ee.Date('2003-02-21'),
        'end': ee.Date('2017-02-28'),
        'leftField': 'system:time_start'
      }))
      .filter(ee.Filter.calendarRange(2, 2, 'month'))
      .filter(ee.Filter.calendarRange(21, 28, 'day_of_year'))
      .map(maskModis)
      .map(addNDVIModis);
    sizeBaseline = colBaseline.size().getInfo();
    console.log('Baseline MODIS images (fallback):', sizeBaseline);
  }

  if (sizeBaseline === 0) {
    console.log('No baseline data (2003-2017).');
    console.log('C1');
    return;
  }

  // Calculate mean NDVI for baseline
  const imgBaseline = colBaseline.mean();
  const countBaseline = imgBaseline.select('NDVI')
    .reduceRegion(reducer=ee.Reducer.count(), geometry=geom, scale=3000, maxPixels=1e9)
    .get('NDVI').getInfo();

  if (countBaseline === 0) {
    console.log('No valid pixels in baseline after masking.');
    console.log('C2');
    return;
  }

  const ndviBaseline = imgBaseline.select('NDVI')
    .reduceRegion(reducer=ee.Reducer.mean(), geometry=geom, scale=3000, maxPixels=1e9)
    .get('NDVI').getInfo();

  console.log('Baseline NDVI (2003-2017, Feb 21-28):', ndviBaseline, '| Valid pixels:', countBaseline);

  // Validation: check for NaN or invalid values
  if (ndvi2019 === null || ndvi2019 === undefined || isNaN(ndvi2019) ||
      ndviBaseline === null || ndviBaseline === undefined || isNaN(ndviBaseline)) {
    console.log('Calculation failed: NaN or invalid values.');
    console.log('C3');
    return;
  }

  // Compare
  console.log('Comparison: 2019 NDVI (' + ndvi2019.toFixed(4) + ') vs Baseline (' + ndviBaseline.toFixed(4) + ')');

  if (ndvi2019 < ndviBaseline) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
